            "p": "หากอย่างอื่นเท่ากัน คู่นี้จะทำให้อัตราความเข้ากันสุดท้ายสูงขึ้น {swingZodiacBanhap} คะแนนในความเข้ากันได้ของราศี และ {swingDayBranchBanhap} คะแนนในความเข้ากันได้ของสาขาวัน เมื่อเทียบกับคู่ที่เป็นกลาง"
